import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format: adjacency matrix or adjacency list
    is_matrix = False
    if n > 0 and isinstance(adj[0], list) and len(adj[0]) == n:
        all_binary = True
        for row in adj:
            if len(row) != n:
                all_binary = False
                break
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build neighbor sets for efficient access
    if is_matrix:
        neighbors = [set(j for j in range(n) if adj[i][j] == 1) for i in range(n)]
    else:
        neighbors = [set(adj[i]) for i in range(n)]
    degree = [len(neighbors[i]) for i in range(n)]

    # Trivial case: no edges
    if all(d == 0 for d in degree):
        return [0] * n

    # Helper: greedy coloring with given vertex order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    # DSATUR heuristic with incremental updates (optimized)
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        deg_uncolored = degree[:]  # current degree in uncolored subgraph

        for _ in range(n):
            if not uncolored:
                break
            # Select vertex with max saturation, tie-break by max deg_uncolored, then random
            v = max(uncolored, key=lambda x: (sat[x], deg_uncolored[x], random.random()))
            # Assign smallest available color
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation and deg_uncolored for neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    if not used[c]:  # This color is new for u's neighborhood
                        sat[u] += 1
                    deg_uncolored[u] -= 1
        return color

    # RLF (Recursive Largest First) heuristic
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len(neighbors[x] & uncolored))
            S = {v}
            # U: vertices not adjacent to any in S (eligible for color c)
            # W: vertices adjacent to at least one in S (ineligible)
            U = uncolored - {v} - (neighbors[v] & uncolored)
            W = neighbors[v] & uncolored
            while U:
                # Select u in U with max |N(u) ∩ W|, tie-break by min degree in G[U], then random
                u = max(U, key=lambda x: (
                    len(neighbors[x] & W),
                    -len(neighbors[x] & U),  # Negative for min degree
                    random.random()
                ))
                S.add(u)
                U.remove(u)
                # Move neighbors of u in U to W
                for nb in neighbors[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color c to all in S
            for vertex in S:
                color[vertex] = c
            uncolored -= S
            c += 1
        return color

    # Smallest-Last (Matula-Beck) ordering
    def smallest_last():
        remaining = set(range(n))
        deg_rem = degree[:]  # Current degrees in remaining subgraph
        removal_order = []
        for _ in range(n):
            v = min(remaining, key=lambda x: deg_rem[x])
            removal_order.append(v)
            remaining.remove(v)
            for u in neighbors[v]:
                if u in remaining:
                    deg_rem[u] -= 1
        # Color in reverse removal order
        return greedy_color(removal_order[::-1])

    # Run heuristics and keep the best
    best_color = None
    best_k = float('inf')

    for heuristic in [dsatur, rlf, smallest_last]:
        color = heuristic()
        k = max(color) + 1 if n > 0 else 0
        if k < best_k:
            best_k = k
            best_color = color[:]

    # Local search with Kempe chains to try to reduce colors
    def kempe_reduce(color_in):
        color = color_in[:]
        k = max(color) + 1 if n > 0 else 0
        if k <= 1:
            return color
        improved = True
        # Limit iterations to avoid timeout; empirical bound for n<=100
        for _ in range(15):  # Balanced iterations for effectiveness and speed
            if not improved:
                break
            improved = False
            # Try to eliminate color classes from highest to lowest
            for target_color in range(k-1, -1, -1):
                # Get vertices with this color
                verts = [v for v in range(n) if color[v] == target_color]
                if not verts:
                    continue
                random.shuffle(verts)  # Randomize to avoid bias
                made_change = False
                for v in verts:
                    # Try direct recoloring to a lower color
                    used = [False] * (target_color + 1)
                    for u in neighbors[v]:
                        c_u = color[u]
                        if c_u < target_color:
                            used[c_u] = True
                    for c in range(target_color):
                        if not used[c]:
                            color[v] = c
                            made_change = True
                            improved = True
                            break
                    if made_change:
                        break
                    # Try Kempe chain swaps for each lower color
                    for c in range(target_color):
                        # Skip if v has no neighbor of color c (direct recoloring would have worked)
                        if not any(color[u] == c for u in neighbors[v]):
                            continue
                        # Build the (target_color, c)-Kempe chain component containing v
                        comp = set()
                        stack = [v]
                        comp.add(v)
                        while stack:
                            node = stack.pop()
                            for nb in neighbors[node]:
                                if color[nb] == target_color or color[nb] == c:
                                    if nb not in comp:
                                        comp.add(nb)
                                        stack.append(nb)
                        # Check if swapping is safe: no neighbor of v in the component has color target_color
                        # (because after swap, such neighbor becomes c, and v becomes c -> conflict)
                        safe = True
                        for u in neighbors[v]:
                            if u in comp and color[u] == target_color:
                                safe = False
                                break
                        if safe:
                            # Perform swap: in component, swap target_color and c
                            for node in comp:
                                if color[node] == target_color:
                                    color[node] = c
                                elif color[node] == c:
                                    color[node] = target_color
                            made_change = True
                            improved = True
                            break
                    if made_change:
                        break
                if made_change:
                    # Recompute k and break to restart from highest color
                    k = max(color) + 1
                    break
        return color

    # Apply Kempe reduction to the best heuristic result
    color_kempe = kempe_reduce(best_color)
    k_kempe = max(color_kempe) + 1 if n > 0 else 0
    if k_kempe < best_k:
        best_k = k_kempe
        best_color = color_kempe[:]

    return best_color

