import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []

    n = len(adj)

    # Detect adjacency matrix vs list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        all_binary = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
        adj = adj_list
    else:
        adj = [list(neighbors) for neighbors in adj]

    if n == 1:
        return [0]

    has_edge = any(len(neighbors) > 0 for neighbors in adj)
    if not has_edge:
        return [0] * n

    degrees = [len(neighbors) for neighbors in adj]

    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * n
            for u in adj[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    best_coloring = None
    best_k = float('inf')

    # DSATUR with dynamic tie-breaking by uncolored degree and random perturbation
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))

        while uncolored:
            max_sat = -1
            candidates = []
            for v in uncolored:
                if sat[v] > max_sat:
                    max_sat = sat[v]
                    candidates = [v]
                elif sat[v] == max_sat:
                    candidates.append(v)

            if max_sat == -1:
                max_deg = -1
                best_v = None
                for v in candidates:
                    deg = sum(1 for u in adj[v] if u in uncolored)
                    if deg > max_deg:
                        max_deg = deg
                        best_v = v
                    elif deg == max_deg:
                        if best_v is None or random.random() < 0.3:
                            best_v = v
                v = best_v
            else:
                max_deg = -1
                best_v = None
                for v in candidates:
                    deg = sum(1 for u in adj[v] if u in uncolored)
                    if deg > max_deg:
                        max_deg = deg
                        best_v = v
                    elif deg == max_deg:
                        if best_v is None or random.random() < 0.3:
                            best_v = v
                v = best_v

            used = [False] * n
            for u in adj[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
            uncolored.remove(v)

            for u in adj[v]:
                if u in uncolored:
                    neighbor_colors = set()
                    for w in adj[u]:
                        if color[w] != -1:
                            neighbor_colors.add(color[w])
                    sat[u] = len(neighbor_colors)

        return color

    # RLF with Kempe-inspired candidate selection (max neighbors in W) and optimized tie-breaking
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0

        while uncolored:
            max_deg = -1
            start = None
            for v in uncolored:
                deg = sum(1 for u in adj[v] if u in uncolored)
                if deg > max_deg:
                    max_deg = deg
                    start = v
                elif deg == max_deg:
                    if start is None or random.random() < 0.3:
                        start = v
            if start is None:
                break

            S = {start}
            U = set()
            W = set()
            for v in uncolored:
                if v == start:
                    continue
                if any(u in adj[v] for u in S):
                    W.add(v)
                else:
                    U.add(v)

            while U:
                best_score = -1
                best_u = None
                for u in U:
                    score = sum(1 for w in adj[u] if w in W)
                    if score > best_score:
                        best_score = score
                        best_u = u
                    elif score == best_score:
                        deg_u = sum(1 for w in adj[u] if w in U)
                        deg_best = sum(1 for w in adj[best_u] if w in U) if best_u is not None else float('inf')
                        if deg_u < deg_best or (deg_u == deg_best and random.random() < 0.3):
                            best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                for w in adj[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)

            for v in S:
                color[v] = c
                uncolored.remove(v)
            c += 1

        return color

    # Independent set extraction guided by dynamic saturation (hybrid) with refined tie-breaking
    def independent_set_by_saturation():
        color = [-1] * n
        uncolored = set(range(n))
        sat = [0] * n
        c = 0

        while uncolored:
            # Select start vertex: max saturation, tie-break by degree in uncolored subgraph
            max_sat = -1
            candidates = []
            for v in uncolored:
                if sat[v] > max_sat:
                    max_sat = sat[v]
                    candidates = [v]
                elif sat[v] == max_sat:
                    candidates.append(v)

            if max_sat == -1:
                max_deg = -1
                start = None
                for v in candidates:
                    deg = sum(1 for u in adj[v] if u in uncolored)
                    if deg > max_deg:
                        max_deg = deg
                        start = v
                    elif deg == max_deg:
                        if start is None or random.random() < 0.3:
                            start = v
            else:
                max_deg = -1
                start = None
                for v in candidates:
                    deg = sum(1 for u in adj[v] if u in uncolored)
                    if deg > max_deg:
                        max_deg = deg
                        start = v
                    elif deg == max_deg:
                        if start is None or random.random() < 0.3:
                            start = v

            if start is None:
                break

            S = {start}
            U = set()
            W = set()
            for v in uncolored:
                if v == start:
                    continue
                if any(u in adj[v] for u in S):
                    W.add(v)
                else:
                    U.add(v)

            while U:
                best_score = -1
                best_u = None
                for u in U:
                    score = sum(1 for w in adj[u] if w in W)
                    if score > best_score:
                        best_score = score
                        best_u = u
                    elif score == best_score:
                        deg_u = sum(1 for w in adj[u] if w in U)
                        deg_best = sum(1 for w in adj[best_u] if w in U) if best_u is not None else float('inf')
                        if deg_u < deg_best or (deg_u == deg_best and random.random() < 0.3):
                            best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                for w in adj[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)

            for v in S:
                color[v] = c
                uncolored.remove(v)

            # Update saturation for uncolored vertices (neighbors of newly colored vertices)
            for v in S:
                for u in adj[v]:
                    if u in uncolored:
                        neighbor_colors = set()
                        for w in adj[u]:
                            if color[w] != -1:
                                neighbor_colors.add(color[w])
                        sat[u] = len(neighbor_colors)

            c += 1

        return color

    # Smallest-Last ordering
    def smallest_last():
        remaining = set(range(n))
        degree = [len(adj[v]) for v in range(n)]
        order = []

        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            d = degree[v]
            buckets[d].append(v)

        min_deg = 0
        for _ in range(n):
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break
            v = buckets[min_deg].pop()
            order.append(v)
            remaining.remove(v)
            for u in adj[v]:
                if u in remaining:
                    d = degree[u]
                    if u in buckets[d]:
                        buckets[d].remove(u)
                    degree[u] -= 1
                    d_new = degree[u]
                    buckets[d_new].append(u)
                    if d_new < min_deg:
                        min_deg = d_new

        return greedy_color(order[::-1])

    # Welsh-Powell
    def welsh_powell():
        order = sorted(range(n), key=lambda x: degrees[x], reverse=True)
        return greedy_color(order)

    # Random greedy
    def random_greedy():
        order = list(range(n))
        random.shuffle(order)
        return greedy_color(order)

    strategies = [
        ("DSATUR", dsatur),
        ("RLF", rlf),
        ("Independent_Set_By_Saturation", independent_set_by_saturation),
        ("Smallest-Last", smallest_last),
        ("Welsh-Powell", welsh_powell),
        ("Random-Greedy", random_greedy)
    ]

    for name, strategy in strategies:
        try:
            coloring = strategy()
            k = count_colors(coloring)
            if k < best_k:
                best_k = k
                best_coloring = coloring[:]
                if k == 1:
                    break
        except Exception:
            continue

    if best_coloring is None:
        best_coloring = welsh_powell()

    # Kempe chain improvement with targeted elimination and early termination
    def kempe_improve(coloring):
        nonlocal best_k
        k = count_colors(coloring)
        if k <= 1:
            return coloring

        target_color = k - 1
        vertices_target = [v for v in range(n) if coloring[v] == target_color]

        for _ in range(3):  # Increased passes for better elimination
