            for v in vertices_target[:]:
                if coloring[v] != target_color:
                    continue
                moved = False
                # Try direct reassignment first (most efficient)
                for c in range(target_color):
                    conflict = False
                    for u in adj[v]:
                        if coloring[u] == c:
                            conflict = True
                            break
                    if not conflict:
                        coloring[v] = c
                        moved = True
                        progress = True
                        break
                if moved:
                    continue
                # Try Kempe chains
                for c in range(target_color):
                    visited = [False] * n
                    stack = [v]
                    visited[v] = True
                    component = []
                    while stack:
                        node = stack.pop()
                        component.append(node)
                        for u in adj[node]:
                            if not visited[u] and (coloring[u] == target_color or coloring[u] == c):
                                visited[u] = True
                                stack.append(u)
                    has_external_c = False
                    for u in adj[v]:
                        if not visited[u] and coloring[u] == c:
                            has_external_c = True
                            break
                    if not has_external_c:
                        for node in component:
                            if coloring[node] == target_color:
                                coloring[node] = c
                            elif coloring[node] == c:
                                coloring[node] = target_color
