            if not progress:
                break

        new_k = count_colors(coloring)
        if new_k < best_k:
            best_k = new_k
        return coloring

    if best_coloring is not None:
        improved = kempe_improve(best_coloring[:])
        if count_colors(improved) < best_k:
            best_coloring = improved

    return best_coloring
